import '@kerfjs/ui/webawesome.css';
import '@awesome.me/webawesome/dist/components/dialog/dialog.js';
import { signal } from 'kerfjs';
import { EmptyState } from '@kerfjs/ui/empty-state';

type Command = { id: string; label: string; group: string };
const commands: Command[] = [{ id: 'new-task', label: 'Create task', group: 'Create' }, { id: 'open-inbox', label: 'Open inbox', group: 'Navigate' }, { id: 'toggle-inspector', label: 'Toggle inspector', group: 'View' }];
// This is intentionally an application composition: the available package has no CommandPalette primitive.
export function createCommandPalette() {
  const open = signal(false); const query = signal(''); const active = signal(0); const recent = signal<string[]>(['open-inbox']);
  const matches = () => commands.filter(command => command.label.toLowerCase().includes(query.value.toLowerCase()));
  const execute = (id: string) => { recent.value = [id, ...recent.value.filter(item => item !== id)].slice(0, 5); open.value = false; document.dispatchEvent(new CustomEvent('app-command', { detail: id })); };
  const render = () => <><button type="button" data-action="open-command-palette" aria-haspopup="dialog">Commands</button><wa-dialog label="Command palette" open={open.value} without-header><section class="command-palette"><label for="command-query">Find a command</label><input id="command-query" type="search" value={query.value} data-action="query-command" aria-controls="command-results" aria-activedescendant={matches()[active.value] ? `command-${matches()[active.value].id}` : undefined} /><div id="command-results" role="listbox" aria-label="Command results">{matches().length ? [...new Set(matches().map(command => command.group))].map(group => <section><h2>{group}</h2>{matches().filter(command => command.group === group).map(command => <button id={`command-${command.id}`} type="button" role="option" aria-selected={matches()[active.value]?.id === command.id} data-action="run-command" data-command={command.id}>{command.label}</button>)}</section>) : <EmptyState title="No commands found" detail="Try a different command name." />}</div><p>Recent: {recent.value.map(id => commands.find(command => command.id === id)?.label).filter(Boolean).join(', ')}</p></section></wa-dialog></>;
  return { render, action(command: string, element: HTMLInputElement | HTMLElement) { if (command === 'open-command-palette') { open.value = true; return; } if (command === 'query-command') { query.value = (element as HTMLInputElement).value; active.value = 0; return; } if (command === 'next-command') { active.value = Math.min(active.value + 1, matches().length - 1); return; } if (command === 'previous-command') { active.value = Math.max(active.value - 1, 0); return; } if (command === 'run-active' && matches()[active.value]) execute(matches()[active.value].id); if (command === 'run-command' && element.dataset.command) execute(element.dataset.command); } };
}
